{"file_path":"tests/test_spec.py","content":""""Regression tests organized by the sections of SPEC.md."""

import pytest

from safety_evals.loader import (
    daily_flag_counts,
    dedupe_transcripts,
    parse_transcript_log,
)
from safety_evals.metrics import (
    flag_rate_by_group,
    flags_in_window,
    longest_flag_streak,
    monitor_flag_rate,
    pooled_flag_rate,
)
from safety_evals.report import monitor_summary, top_flagged_groups


def event(id_, day, flagged):
    return {"id": id_, "day": day, "flagged": flagged}


# Section 1
@pytest.mark.parametrize(
    "flags, expected",
    [([], 0.0), ([None], 0.0), ([False, None], 0.0),
     ([True, None, False, True], 0.5), ([True], 1.0)],
)
def test_monitor_flag_rate_includes_none_in_denominator(flags, expected):
    result = monitor_flag_rate([{"flagged": flag} for flag in flags])
    assert result == expected
    assert isinstance(result, float)


# Section 2
@pytest.mark.parametrize("groups", [{}, {"empty": []}, {"a": [], "b": []}])
def test_pooled_flag_rate_no_transcripts(groups):
    assert pooled_flag_rate(groups) == 0.0


def test_pooled_flag_rate_weights_transcripts_not_groups():
    groups = {
        "small": [{"flagged": True}],
        "large": [{"flagged": False}, {"flagged": None}, {"flagged": False}],
        "empty": [],
    }
    assert pooled_flag_rate(groups) == 0.25


# Section 3
@pytest.mark.parametrize(
    "counts, days, expected",
    [([1, 2, 4], 0, 0), ([1, 2, 4], 1, 4), ([1, 2, 4], 2, 6),
     ([1, 2, 4], 3, 7), ([1, 2, 4], 10, 7), ([], 0, 0), ([], 5, 0)],
)
def test_flags_in_window(counts, days, expected):
    assert flags_in_window(counts, days) == expected


# Section 4
@pytest.mark.parametrize("flag, expected", [("1", True), ("0", False), ("", None)])
def test_parse_transcript_log_flag_values_and_whitespace(flag, expected):
    result = parse_transcript_log([f"  x1 \t, -3 , {flag} \t\n"])
    assert result == [event("x1", -3, expected)]
    assert result[0]["flagged"] is expected


def test_parse_transcript_log_skips_blank_and_comment_lines():
    lines = ["", " \t\n", "# comment", "  \t# another,comment", "x,1,0",
             "\n", " # trailing comment", "y,2,"]
    assert parse_transcript_log(iter(lines)) == [event("x", 1, False), event("y", 2, None)]
    assert parse_transcript_log(lines[:4]) == []
    assert parse_transcript_log([]) == []


@pytest.mark.parametrize("bad_line", ["x,1", "x,1,0,extra", "x", "x,no,1", "x,1.5,0", "x,,1"])
def test_parse_transcript_log_errors_include_input_line_number(bad_line):
    with pytest.raises(ValueError, match=r"\bline 5\b"):
        parse_transcript_log(["", " # comment", "x,1,1", " \t", bad_line])


# Section 5

def test_dedupe_transcripts_keeps_last_duplicate_id_and_sorts():
    old = event("a", 0, True)
    last = event("a", 3, None)
    b = event("b", 3, True)
    c = event("c", 1, False)
    events = [old, b, c, event("a", 5, False), last]
    assert dedupe_transcripts(events) == [c, last, b]
    assert events == [old, b, c, event("a", 5, False), last]
    assert dedupe_transcripts([]) == []


# Section 6

def test_daily_flag_counts_inclusive_range_and_missing_days():
    events = [event("before", 0, True), event("after", 6, True),
              event("a", 1, True), event("b", 1, True),
              event("c", 3, False), event("d", 4, None), event("e", 5, True)]
    assert daily_flag_counts(events, 1, 5) == [2, 0, 0, 0, 1]
    assert daily_flag_counts(events, 1, 1) == [2]
    assert daily_flag_counts(events, 5, 1) == []


@pytest.mark.parametrize("start, end, expected", [(1, 3, [0, 0, 0]), (-1, 1, [0, 0, 0]), (2, 1, [])])
def test_daily_flag_counts_empty_events(start, end, expected):
    assert daily_flag_counts([], start, end) == expected


# Section 7
@pytest.mark.parametrize("days, recent", [(0, 0), (1, 0), (2, 1), (3, 1), (10, 2)])
def test_monitor_summary_pooled_rounded_rate_and_calendar_window(days, recent):
    groups = {
        "small": [event("a", 1, True)],
        "large": [event("b", 1, False), event("c", 4, True),
                  event("d", 5, None), event("e", 5, False), event("f", 5, False)],
        "empty": [],
    }
    assert monitor_summary(groups, days) == {"rate": 0.333, "recent": recent, "groups": 2}


@pytest.mark.parametrize("groups", [{}, {"empty": []}])
def test_monitor_summary_no_transcripts(groups):
    assert monitor_summary(groups, 5) == {"rate": 0.0, "recent": 0, "groups": 0}


# Section 8
@pytest.mark.parametrize("n, expected", [(0, []), (1, ["best"]), (3, ["best", "a", "z"]),
                                         (10, ["best", "a", "z", "zero"])])
def test_top_flagged_groups_order_ties_and_empty_groups(n, expected):
    groups = {
        "z": [{"flagged": True}, {"flagged": None}],
        "zero": [{"flagged": False}],
        "empty": [],
        "a": [{"flagged": True}, {"flagged": False}],
        "best": [{"flagged": True}],
    }
    assert top_flagged_groups(groups, n) == expected


@pytest.mark.parametrize("groups", [{}, {"empty": []}])
def test_top_flagged_groups_no_qualifying_groups(groups):
    assert top_flagged_groups(groups, 3) == []


# Section 9

def test_flag_rate_by_group_sorted_keys_and_empty_group():
    groups = {"z": [{"flagged": True}, {"flagged": None}], "empty": [],
              "a": [{"flagged": False}]}
    result = flag_rate_by_group(groups)
    assert result == {"a": 0.0, "empty": None, "z": 0.5}
    assert list(result) == ["a", "empty", "z"]
    assert flag_rate_by_group({}) == {}


# Section 10
@pytest.mark.parametrize(
    "counts, expected",
    [([], 0), ([0, 0], 0), ([-1, 0, -2], 0), ([1, 2, 3], 3),
     ([1, 0, 1, 2, 0, 1], 2), ([1, -1, 2], 1), ([0, 1, 1, 1], 3)],
)
def test_longest_flag_streak(counts, expected):
    assert longest_flag_streak(counts) == expected
